-- The Morning Glory (spiritsoffrenchlick.com/spirits-all/the-morning-glory): the maker's Bottled-in-Bond Kasha Bourbon, 100 proof, inserted as its own row.
-- The seed rows (109 proof / 4.5 yr, "Office Cigar Lounge Barrel Pick") are NOT corrected: a 109-proof pick cannot be the BiB bottle. Applied 2026-10-11.
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"The Morning Glory Bottled in Bond Kasha Bourbon","rar":"limited","f":"The Morning Glory","x":"Bottled in Bond Kasha Bourbon","p":100.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":true,"bp":false,"fin":null,"msrp":null,"core":true,"al2":[],"img":"https://static1.squarespace.com/static/5c09281536099ba88710e914/5c0952ea4fa51a479f4e077f/642c46064a46ed3b232837d5/1784912896690/Glory+-+Square.jpg?format=1500w","u":"https://www.spiritsoffrenchlick.com/spirits-all/the-morning-glory","pr":"Spirits of French Lick","mk":"dc6b6aa9-f81e-42eb-b56d-81014d702dc5"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
